// Parse FAOSTAT indicators — fix: handle n8n split items
// Helper: parse FAOSTAT response from node robustly
function extractLatestFAO(items) {
  let dataArray = [];
  for (const item of items) {
    if (item.data) {
       let inner = typeof item.data === 'string' ? JSON.parse(item.data) : item.data;
       if (Array.isArray(inner) && Array.isArray(inner[1])) dataArray.push(...inner[1]);
       else if (Array.isArray(inner)) dataArray.push(...inner);
       else dataArray.push(inner);
    } else if (Array.isArray(item)) {
       if (Array.isArray(item[1])) dataArray.push(...item[1]);
       else dataArray.push(...item);
    } else {
       dataArray.push(item);
    }
  }
  return dataArray.find(r => r && r.value !== null && r.value !== undefined && r.value !== '');
}

function tryGetItems(nodeName) {
  if (nodeName === 'Fetch Crop Production Index') { try { return $('Fetch Crop Production Index').all().map(i => i.json); } catch(e) {} }
  if (nodeName === 'Fetch Food Production Index') { try { return $('Fetch Food Production Index').all().map(i => i.json); } catch(e) {} }
  if (nodeName === 'Fetch Fertilizer Consumption') { try { return $('Fetch Fertilizer Consumption').all().map(i => i.json); } catch(e) {} }
  return [];
}

const indicators = [
  { node: 'Fetch Crop Production Index', commodity: 'Agricultural Products', metric: 'crop_production_index', unit: 'index (2014-16=100)' },
  { node: 'Fetch Food Production Index', commodity: 'Agricultural Products', metric: 'food_production_index', unit: 'index (2014-16=100)' },
  { node: 'Fetch Fertilizer Consumption', commodity: 'Agricultural Products', metric: 'fertilizer_consumption', unit: 'kg/ha arable land' }
];

const rows = [];
for (const ind of indicators) {
  const latest = extractLatestFAO(tryGetItems(ind.node));
  if (latest) {
    rows.push({
      source: 'FAOSTAT',
      commodity: ind.commodity,
      metric: ind.metric,
      value: Math.round(latest.value * 100) / 100,
      unit: ind.unit,
      period: latest.date
    });
  }
}

if (rows.length === 0) {
  return [{ json: { source: 'FAOSTAT', commodity: 'Agricultural Products', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}

return rows.map(r => ({ json: r }));
